pub(crate) fn list_rx_is_empty(rx: &super::list::Rx<T>, tx: &super::list::Tx<T>) -> bool {
    let block = unsafe { rx.head.as_ref() };
    let _ = block.touch_header_inspectors(rx.index);
    // The head block may not have been advanced yet even though `rx.index`
    // already points into the next block. In that case, the current index
    // must not be looked up in the old block, as its ready bits belong to
    // a different range of slot indices.
    let has = block.is_at_index(start_index(rx.index)) && block.has_value(rx.index);
    let bits = block.load_ready_bits();

