input.content:
use tokio::sync::mpsc;

#[tokio::main]
async fn main() {
    for cap in [1, 2, 33] {
        let (sender, mut receiver) = mpsc::channel(cap);
        for value in 1..257 {
            sender.send(value).await.unwrap();
            receiver.recv().await.unwrap();
            assert!(receiver.is_empty(), "bounded cap {cap}, {value}, len {}", receiver.len());
        }
    }

    let (sender, mut receiver) = mpsc::unbounded_channel();
    for value in 1..257 {
        sender.send(value).unwrap();
        receiver.recv().await.unwrap();
        assert!(receiver.is_empty(), "unbounded {value}, len {}", receiver.len());
    }
}
